oto_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('jimmy-puah-wee-tse','hassan-abdul-karim','suhaizan-kaiat') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0046: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0046:jimmy-puah-wee-tse:surau-assistance-report','Report RM40,000 in assistance for a Tebrau surau','Community Development','achieved',null,null,null,null,'2026-05-17','https://www.pmo.gov.my/en/uncategorized/teks-ucapan-verbatim-yab-perdana-menteri-majlis-ramah-mesra-yab-perdana-menteri-bersama-rakyat/','The Prime Minister’s published Desa Mutiara Tebrau speech records Jimmy Puah’s RM40,000 contribution for a surau.','Achieved covers only the reported contribution. The transcript does not establish the exact earlier handover date, the surau’s completed works or subsequent use of the funds.','2026-11-10','editorial',false from public.entities e where e.slug='jimmy-puah-wee-tse' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0046:suhaizan-kaiat:ceria-ke-sekolah-2026','Distribute back-to-school assistance to more than 100 Pulai students','Education','achieved',null,null,null,null,'2026-01-07','https://malaysiaaktif.my/2026/01/pelajar-di-parlimen-pulai-terima-bantuan-kelengkapan-persekolahan/','Suhaizan’s service centre and TNB Johor Bahru delivered school-preparation support at the 6 January programme. TNB contributed RM10,000 and eligible recipients received RM150 redemption vouchers.','Published 7 January about the previous day’s programme. Achieved covers the reported assistance round, jointly delivered with TNB; it does not establish universal eligibility coverage or later redemption totals.','2026-11-10','editorial',false from public.entities e where e.slug='suhaizan-kaiat' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

